"""Compare full corrected native histories against the original declared mechanical references."""
from probe_aircraft_a47 import *
from audit_aircraft_a05 import histories,vtk

def table(H,prefix,components):
 keys=[k for k in H if k.startswith(prefix)];ids=[int(k.split()[1]) for k in keys][::components];assert len(keys)==len(ids)*components;return np.column_stack([H[k] for k in keys]).reshape(len(H['time']),len(ids),components)[:,np.argsort(ids),:]

def review(mode,method):
 c=read(CFG);d=OUT/'encoding_repair'/mode/method;g=read(d/'generation.json');n=g['name'];H=histories(d/(n+'T01.csv'));T=H['time'];a=c['acceptance'];r=c['reference'];A=np.asarray(g['nodal_amplitudes']);N=table(H,'NATIVE_MOTION',3 if mode=='MEMBRANE' else 6);Q=table(H,'NATIVE_RESULTANTS',8);v=table(H,'NATIVE_VELOCITY',6);reac=table(H,'NATIVE_REACTION',6);s=np.interp(T,c['load']['times_ms'],c['load']['normalized_values']);ref=A[None,:,:N.shape[2]]*s[:,None,None];boundary=np.asarray(c['boundary_node_ids'])-1;dx=float(abs(N[:,boundary,:3]-ref[:,boundary,:3]).max());rot=float(abs(N[:,boundary,3:]-ref[:,boundary,3:]).max()) if mode=='BENDING' else None
 target=r['membrane_energy_J' if mode=='MEMBRANE' else 'bending_energy_J'];expected=s*s*target;E=sum(H[k] for k in ['KINETIC ENERGY','ROTATION ENERGY','INTERNAL ENERGY','HOURGLASS ENERGY','SPRING ENERGY','ELASTIC CONTACT ENERGY','FRICTIONAL CONTACT ENERGY','DAMPING CONTACT ENERGY '])*.001;EW=H['EXTERNAL WORK']*.001;IE=H['INTERNAL ENERGY']*.001;res=E-E[0]-EW;channels=[(0,r['membrane_F1_MPa']),(1,r['membrane_F2_MPa'])] if mode=='MEMBRANE' else [(3,r['bending_M1_MPa']),(4,r['bending_M2_MPa'])];maxerr=max(float(abs(Q[:,:,j]-s[:,None]*val).max()) for j,val in channels);denom=max(abs(val) for j,val in channels);energyerr=float(abs(IE[-1]-target)/target);et=a['energy_fraction']*max(float(abs(E).max()),float(abs(EW).max()),target)+a['absolute_energy_J'];work_increment=np.sum(np.mean(v[1:]+v[:-1],axis=0)*0) if False else float(np.sum(.5*(v[1:]+v[:-1])*np.diff(reac,axis=0))*.001)
 checks={'native_full_window':read(d/'full_window_review.json')['pass'],'fresh_Starter_strict':read(d.parent/'preparation/starter_gate.json')['pass'],'finite_histories':all(np.isfinite(x).all() for x in H.values()),'mass_matches_patch':bool(abs(H['MASS']-c['patch']['expected_mass_g']).max()<=a['mass_relative']*c['patch']['expected_mass_g']),'no_added_mass':bool(abs(H['ADDED MASS']).max()<=a['added_mass_relative']*c['patch']['expected_mass_g']),'prescribed_displacements':dx<=a['prescribed_displacement_mm'],'native_global_work_energy':float(abs(res).max())<=et,'no_plastic_work':float(abs(H['PLASTIC WORK']*.001).max())<=a['no_plastic_work_J'],'entered_thickness_unchanged':bool(abs(Q[:,:,7]-r['thickness_mm']).max()<1e-5),'no_erosion':bool(np.all(Q[:,:,6]>0)),'independent_end_internal_energy':energyerr<=a['analytic_membrane_energy_fraction' if mode=='MEMBRANE' else 'analytic_bending_energy_fraction'],'independent_force_or_moment_resultants':maxerr<=a['analytic_resultant_fraction']*denom+a['force_or_moment_absolute_MPa']}
 if rot is not None:checks['prescribed_rotations']=rot<=a['prescribed_rotation_rad']
 result={'created_utc':now(),'mode':mode,'method':method,'samples':len(T),'first_ms':float(T[0]),'last_ms':float(T[-1]),'checks':checks,'pass':all(checks.values()),'failed_checks':[k for k,v in checks.items() if not v],'maximum_prescribed_displacement_error_mm':dx,'maximum_prescribed_rotation_error_rad':rot,'end_IE_J':float(IE[-1]),'reference_IE_J':target,'end_IE_relative_error':energyerr,'maximum_energy_residual_J':float(abs(res).max()),'energy_tolerance_J':et,'maximum_force_or_moment_normalized_resultant_error_MPa':maxerr,'resultant_reference_scale_MPa':denom,'max_plastic_work_J':float(abs(H['PLASTIC WORK']*.001).max()),'reaction_trapezoid_work_J_diagnostic':work_increment,'external_work_J':float(EW[-1]),'reaction_diagnostic_scope':'Raw REAC channels and translational/angular published velocities retained; no force semantics imposed on implicit secant fields or restart. Resultant validation uses native F/M shell channels and primary documented thickness normalization.','whole_impact_qualified':False};dump(d/'mechanical_review.json',result);np.savez_compressed(d/'mechanical_diagnostics.npz',time_ms=T,native_IE_J=IE,independent_IE_J=expected,native_total_J=E,native_external_J=EW,native_residual_J=res,native_motion=N,native_resultants=Q);return result,H,N,Q

def assess():
 guard();assert not (OUT/'loaded_shell_review.json').exists();execution=read(OUT/'encoding_repair_execution_review.json');assert len(execution['cases'])==4 and all(x['raw_exit_normal'] for x in execution['cases']);rows=[];pairs=[];c=read(CFG);a=c['acceptance']
 for mode in MODES:
  values=[review(mode,method) for method in ['EXPLICIT','IMPLICIT']];rows.extend(x[0] for x in values);hs=[x[1] for x in values];tt=hs[0]['time'];lo=max(h['time'][0] for h in hs);hi=min(h['time'][-1] for h in hs);tt=tt[(tt>=lo)&(tt<=hi)];target=c['reference']['membrane_energy_J' if mode=='MEMBRANE' else 'bending_energy_J'];energy={}
  for key in ['INTERNAL ENERGY','KINETIC ENERGY','ROTATION ENERGY','EXTERNAL WORK']:
   v=[np.interp(tt,h['time'],h[key])*.001 for h in hs];error=float(abs(v[0]-v[1]).max());tol=a['explicit_implicit_energy_fraction']*target+a['absolute_energy_J'];energy[key]={'maximum_difference_J':error,'tolerance_J':tol,'pass':error<=tol}
  nodal=[x[2] for x in values];interp=[np.column_stack([np.interp(tt,hs[i]['time'],node[:,j,k]) for j in range(9) for k in range(3)]) for i,node in enumerate(nodal)];delta=float(abs(interp[0]-interp[1]).max());state=[OUT/'encoding_repair'/mode/method/f'A47_R1_{mode}_0000_0001.rst' for method in ['EXPLICIT','IMPLICIT']];pair={'mode':mode,'first_common_ms':float(tt[0]),'last_common_ms':float(tt[-1]),'samples_common':len(tt),'energy':energy,'maximum_nodal_displacement_difference_mm':delta,'same_initial_state_sha256':streamsha(state[0])==streamsha(state[1]),'all_individual_checks':all(x[0]['pass'] for x in values),'pass':all(x['pass'] for x in energy.values()) and delta<=a['explicit_implicit_displacement_mm'] and all(x[0]['pass'] for x in values),'comparison_on_recorded_common_support_only':True,'no_time_shift_or_extrapolation':True};pairs.append(pair);print({'mode':mode,'individual_passes':[x[0]['pass'] for x in values],'failed_checks':[x[0]['failed_checks'] for x in values],'pair_pass':pair['pass'],'IE_errors':[x[0]['end_IE_relative_error'] for x in values]},flush=True)
 dump(OUT/'loaded_shell_review.json',{'created_utc':now(),'cases':rows,'explicit_implicit_pairs':pairs,'all_pass':all(x['pass'] for x in rows+pairs),'corrected_input_matches_original_declaration':True,'original_criteria_unchanged':True,'old_failures_preserved':True,'whole_impact_qualified':False,'new_whole_time_credit_s':0})

if __name__=='__main__':assess()
